def with_history(component):
    def deco(handler):
        @functools.wraps(handler)
        def wrapper(msg):
            hops = json.loads(header(msg, "history") or b"[]")
            hops.append({"name": component, "ts": time.time()})
            set_header(msg, "history", json.dumps(hops).encode())
            return handler(msg)
        return wrapper
    return deco
